values.content:
=Classify the following email.

From: {{ $json.from }}
Subject: {{ $json.subject }}
Body: {{ $json.body }}

parameters.message:
="This email requires your attention.

        From: {{ $('Received Email').item.json.from }}
        Category: {{ $('Get Parameters').item.json.subcategory }} and {{ $('Get Parameters').item.json.subcategory }}
        Priority: {{ $('Get Parameters').item.json.priority }}

        --- Original message ---
        {{ $('Received Email').item.json.body }}"

parameters.jsCode:
const raw = $input.item.json.output[0].content[0].text;
const parsed = JSON.parse(raw);

return {
  json: {
    category: parsed.category,
    subcategory: parsed.subcategory,
    can_auto_respond: parsed.can_auto_respond,
    priority: parsed.priority,
    escalate_to: parsed.escalate_to,
    sender_email: parsed.sender_email,
    search_query: parsed.search_query
  }
};;

